Lemma rs_inv_stack : forall (ra sp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word)
    (bs stb ioc implb MB tgt tn ec spa lo shi ff fp : Z) (LB : list block) (LF : list fframe) (S : statev) (ds junk : list byte) (E : ecv)
    (m mx mx' : mem),
  rs_inv H ra sp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 bs stb ioc implb MB tgt tn ec spa lo shi ff fp LB LF S ds junk E m mx ->
  munch [(lo, spa)]%Z mx mx' -> wmono bsegs mx mx' -> mem_inv bsegs mx' -> stk bsegs mx' lo spa ->
  rs_inv H ra sp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 bs stb ioc implb MB tgt tn ec spa lo shi ff fp LB LF S ds junk E m mx'.
Proof.
  intros until mx'. intros INV MU WM MI' ST'.
  destruct INV as (p & j7 & j16 & j4 & hj & hk & sha & shb & t0j & t1j & gap & TMP & GAP & GSZ & SPA & SAVED & FRM & SHU & FL & STc & MI & RFc & FF & ACc & SKc & RF & MU2 & WM2
                   & IN & RB & CH & OK & EV & CE & CW & PMC & ALM & FB & PC & CO & E1 & E2 & E2' & E3 & E3' & AD & EOF
                   & RBS & BS8 & APB & FOB & ACB & SEPB & MBC & MB8 & APM & FOM & ACM & SEPM & TGT & TN & APT & TGH & FOT & ACT & SVT
                   & ECC & EC8 & APE & FOE & ACE & SEPE & XS & MV & FOS & FOF & DTS & DTF & DTE & DTM & DES & DEM & DEB & DBS & DMS & DTB & DEF & DSF & LO & CEIL & RA).
  sp_range sp. pose proof aceil_facts as (AF1 & AF2 & AF3). assert (AIS : AINTRIN_STACK = 4096) by reflexivity.
  pose proof (ff_facts _ _ _ _ _ FF) as (_ & _ & _ & _ & F1 & F2 & F3 & _ & F4 & F5 & F6 & F7 & F8 & F9 & F10 & F11 & F12 & APF & APP1 & SHFF & SF1 & SF2 & SF3 & NSB).
  fs_nums_in F2. fs_nums_in F9. fs_nums_in SF2. fs_nums_in SF3.
  pose proof (rblock_bounds _ _ RB) as (R1 & R2 & R3 & R4 & R5 & R6). pose proof RB as (_ & R16 & _ & APS & _).
  pose proof APB as (BB4 & BB1 & BB3 & NSBS). pose proof APM as (MM4 & MM1 & MM3 & NSM).
  pose proof (aapp_bounds _ _ APE ltac:(clear; lia)) as (EE1 & EE2 & EE3 & EE4 & EE5).
  pose proof (aapp_bounds _ _ APT ltac:(clear - TN; lia)) as (TT1 & TT2 & TT3 & TT4 & TT5).
  pose proof (rw_cells_bound _ _ _ _ TGT) as TGB. cbn [cells_size csize Nat.add length] in TGB.
  unfold AREADSOME_STACK in LO. rewrite AIS in LO.
  assert (SPAR : bv_unsigned sp + -176 <= spa <= bv_unsigned sp + -160) by (clear - SPA; lia).
  assert (WFS : Forall (win_fs0 ff) [(lo, spa)]%Z) by (apply Forall_cons; [unfold win_fs0; cbn [fst snd]; right; left; unfold AHI_LO; clear - CEIL AF1; lia| apply Forall_nil]).
  assert (W3K : Forall (fun iv : Z * Z => aceil <= fst iv \/ (ff <= fst iv /\ snd iv <= ff + fsz 0)
                              \/ (Z.shiftr ff 3 + 2147450880 <= fst iv /\ snd iv <= Z.shiftr ff 3 + 2147450880 + fshn 0)
                              \/ (exists O n, fsobj H LF O n /\ aplace O n /\ 0 <= n /\ O <= fst iv /\ snd iv <= O + n)) [(lo, spa)]%Z)
    by (apply Forall_cons; [cbn [fst snd]; left; exact CEIL| apply Forall_nil]).
  assert (WH : wins_hi [(lo, spa)]%Z) by (apply Forall_cons; [cbn [fst snd]; right; unfold AHI_LO; clear - CEIL AF1; lia| apply Forall_nil]).
  pose proof (fs_frame_writes_pl _ HH _ _ _ _ _ _ _ _ _ RFc ACc SKc FF MU WM W3K) as (RF1 & AC1 & SK1).
  (* [comment removed for export] *)
  Local Ltac mv K MU WM tac := first [ eapply rw_cells_transport in K; [| exact MU| exact WM| cbn [disjoint_from fst snd cells_size csize Nat.add length]; split; [tac| exact I]]
                               | eapply ro_cells_transport in K; [| exact MU| cbn [disjoint_from fst snd cells_size csize Nat.add length]; split; [tac| exact I]] ].
  mv TMP MU WM ltac:(right; clear; lia). mv GAP MU WM ltac:(right; clear; lia). mv SAVED MU WM ltac:(unfold fbp_saved; cbn [cells_size csize Nat.add length]; right; clear - SPAR; lia).
  mv FRM MU WM ltac:(left; clear - F2 CEIL; lia). mv SHU MU WM ltac:(left; rewrite <- SHFF in SF2; clear - SF2 AF1 CEIL; unfold AHI_LO in *; lia). mv FL MU WM ltac:(left; clear - F5 F2 CEIL; lia).
  mv CH MU WM ltac:(unfold SpcHdrCells; cbn [cells_size csize Nat.add length]; left; clear - R5 CEIL; unfold SZ_SPCI_STATE in *; lia).
  mv CE MU WM ltac:(unfold AnyExecCells; cbn [cells_size csize Nat.add length]; left; clear - R5 CEIL; unfold SZ_SPCI_STATE in *; lia).
  mv CW MU WM ltac:(left; clear - R5 CEIL; unfold SZ_SPCI_STATE in *; lia). mv PMC MU WM ltac:(unfold PMutexCells, zeros; cbn [cells_size csize Nat.add length repeat]; left; clear - R5 CEIL; unfold SZ_SPCI_STATE in *; lia).
  mv CO MU WM ltac:(left; clear - R5 CEIL; unfold SZ_SPCI_STATE in *; lia).
  mv RBS MU WM ltac:(clear - SEPB SPAR; lia). mv MBC MU WM ltac:(clear - SEPM SPAR; lia). mv TGT MU WM ltac:(left; rewrite ?Nat.add_0_r, Z2Nat.id by (clear - TN; lia); clear - TGH CEIL; lia).
  mv ECC MU WM ltac:(unfold ErrCodeCells; cbn [cells_size csize Nat.add length]; clear - SEPE SPAR; lia).
  exists p, j7, j16, j4, hj, hk, sha, shb, t0j, t1j, gap.
  split; [exact TMP|]. split; [exact GAP|]. split; [exact GSZ|]. split; [exact SPA|]. split; [exact SAVED|]. split; [exact FRM|]. split; [exact SHU|]. split; [exact FL|].
  split; [exact ST'|]. split; [exact MI'|]. split; [exact RF1|]. split; [exact FF|]. split; [exact AC1|]. split; [exact SK1|]. split; [exact RF|].
  split; [eapply munch_extend; [exact MU2| exact MU| unfold sub_fp, rs_W; cbn [outside]; clear - SPAR; intros x Hx; lia]|].
  split; [exact (wmono_trans bsegs _ _ _ WM2 WM)|].
  split; [exact IN|]. split; [exact RB|]. split; [exact CH|]. split; [exact OK|]. split; [exact EV|]. split; [exact CE|]. split; [exact CW|]. split; [exact PMC|]. split; [exact ALM|].
  split.
  { eapply (AFlatBuf_fs0 _ HH); [exact RF| exact FF| exact FB| intros NE; exact (proj1 (FOF NE))| exact MU| exact WM| exact WFS
      | unfold SZ_FB; cbn [disjoint_from fst snd]; split; [left; clear - R5 CEIL; unfold SZ_SPCI_STATE in *; lia| exact I]
      | intros NE; destruct FB as (_ & FOK & _); destruct FOK as [EE|(q & INq & RBq & CAP & _)]; [contradiction|];
        pose proof (rblock_bounds _ _ RBq) as (C1 & C2 & C3 & C4 & C5 & C6); cbn [disjoint_from fst snd]; split; [left; clear - C5 CEIL; lia| exact I] ]. }
  split; [eapply APCond_transport; [exact PC| exact MU| exact WM| unfold SZ_PCOND; cbn [disjoint_from fst snd]; split; [left; clear - R5 CEIL; unfold SZ_SPCI_STATE in *; lia| exact I]]|].
  split; [exact CO|]. split; [exact E1|]. split; [exact E2|]. split; [exact E2'|]. split; [exact E3|]. split; [exact E3'|].
  split; [exact (addressable_fs0 _ HH ff fp LF m mx mx' stb SZ_SPCI_STATE _ RF FF FOS APS ltac:(unfold SZ_SPCI_STATE; clear; lia) AD MU WM WFS)|].
  split; [exact EOF|].
  split; [exact RBS|]. split; [exact BS8|]. split; [exact APB|]. split; [exact FOB|]. split; [eapply accessible_transport_hi; [exact ACB| exact MU| exact WH]|]. split; [exact SEPB|].
  split; [exact MBC|]. split; [exact MB8|]. split; [exact APM|]. split; [exact FOM|]. split; [eapply accessible_transport_hi; [exact ACM| exact MU| exact WH]|]. split; [exact SEPM|].
  split; [exact TGT|]. split; [exact TN|]. split; [exact APT|]. split; [exact TGH|]. split; [exact FOT|]. split; [eapply accessible_transport_hi; [exact ACT| exact MU| exact WH]|].
  split; [eapply shvis_transport_hi; [exact SVT| exact MU| exact WM| clear - TT4 TN; lia| clear - TT3; lia| exact WH]|].
  split; [exact ECC|]. split; [exact EC8|]. split; [exact APE|]. split; [exact FOE|]. split; [eapply accessible_transport_hi; [exact ACE| exact MU| exact WH]|]. split; [exact SEPE|].
  split; [eapply AXStatics2_transport; [exact XS| exact MU| exact WM| apply Forall_cons; [cbn [fst snd]; left; clear - CEIL AF1; unfold AHI_LO in *; lia| apply Forall_nil]]|].
  split; [unfold AMiscVt48 in *; eapply ro_cells_transport; [exact MV| exact MU| unfold AW_MISC_CAT_VT48, AW_MISC_CAT_VPTR; cbn [disjoint_from fst snd cells_size csize Nat.add length]; split; [left; clear - CEIL AF1; unfold AHI_LO in *; lia| exact I]]|].
  split; [exact FOS|].
  split.
  { intros NE. destruct (FOF NE) as [FOQ SVQ]. split; [exact FOQ|].
    destruct FB as (_ & FOK & _); destruct FOK as [EE|(q & INq & RBq & CAP & _ & BOLE)]; [contradiction|].
    pose proof (rblock_bounds _ _ RBq) as (C1 & C2 & C3 & C4 & C5 & C6). unfold fb_cap in *.
    eapply shvis_transport_hi; [exact SVQ| exact MU| exact WM| clear - C1 CAP; lia| clear - C3; lia| exact WH]. }
  split; [exact DTS|]. split; [exact DTF|]. split; [exact DTE|]. split; [exact DTM|]. split; [exact DES|]. split; [exact DEM|]. split; [exact DEB|].
  split; [exact DBS|]. split; [exact DMS|]. split; [exact DTB|]. split; [exact DEF|]. split; [exact DSF|].
  split; [unfold AREADSOME_STACK; rewrite AIS; exact LO|]. split; [exact CEIL| exact RA].
Qed.
